#include <stdio.h>
#include <string.h>

int main(void) {
    long long r0 = 0, r1 = 0;
    long long *cur = &r0;
    char cmd[10];
    while (scanf("%9s", cmd) == 1) {
        if (strcmp(cmd, "show") == 0) {
            printf("%lld %lld\n", r0, r1);
            continue;
        }
        long long k;
        scanf("%lld", &k);
        if (strcmp(cmd, "sel") == 0) {
            cur = k == 0 ? &r0 : &r1;
        } else if (strcmp(cmd, "add") == 0) {
            *cur += k;
        } else if (strcmp(cmd, "mul") == 0) {
            *cur *= k;
        }
    }
    return 0;
}

