#include <stdio.h>

int main(void) {
    int a[1000];
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    int pos = 0;
    int *cur = &a[pos];
    char cmd;
    while (scanf(" %c", &cmd) == 1) {
        if (cmd == 'L' && pos > 0) {
            pos--;
            cur = &a[pos];
        } else if (cmd == 'R' && pos < n - 1) {
            pos++;
            cur = &a[pos];
        } else if (cmd == '+' || cmd == '=') {
            int k;
            scanf("%d", &k);
            if (cmd == '+') {
                *cur += k;
            } else {
                *cur = k;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", a[i]);
    }
    printf("\n");
    return 0;
}

